<?php

/**
 * @file
 * Committed Drupal settings: NO secrets in here.
 *
 * Database credentials and the hash salt come from:
 * - settings.ddev.php (generated by `ddev start`, git-ignored), or
 * - settings.local.php (your own machine, git-ignored).
 */

$databases = [];

// Config lives outside the web root and is versioned in git.
// Workflow: change config in the UI -> `drush cex` -> commit -> on another
// environment `drush cim`.
$settings['config_sync_directory'] = '../config/sync';

$settings['update_free_access'] = FALSE;
$settings['container_yamls'][] = $app_root . '/' . $site_path . '/services.yml';
$settings['file_scan_ignore_directories'] = ['node_modules', 'bower_components'];
$settings['entity_update_batch_size'] = 50;
$settings['entity_update_backup'] = TRUE;
$settings['state_cache'] = TRUE;
$settings['migrate_node_migrate_type_classic'] = FALSE;

// Automatically generated include for settings managed by DDEV.
if (getenv('IS_DDEV_PROJECT') == 'true' && file_exists(__DIR__ . '/settings.ddev.php')) {
  include __DIR__ . '/settings.ddev.php';
}

if (file_exists($app_root . '/' . $site_path . '/settings.local.php')) {
  include $app_root . '/' . $site_path . '/settings.local.php';
}
